/// <summary>
/// VendEditInvoice form VendInvoiceInfoLine datasource extension
/// </summary>
[ExtensionOf(formDataSourceStr(VendEditInvoice, VendInvoiceInfoLine))]
final class METVendEditInvoiceFDS_VendInvoiceInfoLine_Extension
{
}

Method.Source:
/// <summary>
/// Update reason code data.
/// </summary>
public void executeQuery()
{
    next executeQuery();

    if (METVendParameters::find().EnableMetcashMatchingLogic)
    {
        FormDataSource VendInvoiceInfoLineFDS = this;
        VendInvoiceInfoLine VendInvoiceInfoLine = VendInvoiceInfoLineFDS.cursor();
    }
}

/// <summary>
/// Write method to handle any additional logic when writing the VendInvoiceInfoLine record.
/// </summary>
void write()
{
    next write();

    element.refresh();
}

/// <summary>
/// Override active method to enforce read-only properties of reason/claim fields for No Delivery lines.
/// </summary>
/// <returns>active result</returns>
public int active()
{
    int ret = next active();

    this.metSetNoDeliveryFieldsEditable();

    return ret;
}

/// <summary>
/// Sets reason code and claim line fields to read-only if the line is a No Delivery service item line.
/// </summary>
private void metSetNoDeliveryFieldsEditable()
{
    VendInvoiceInfoLine line = this.cursor();
    boolean isNoDelivery = false;

    if (line.ItemId)
    {
        ReasonTable reasonCode = line.metGetNoDeliveryReasonCode();
        if (reasonCode.RecId)
        {
            isNoDelivery = true;
        }
    }

    this.formRun().control(this.formRun().controlId(formControlStr(VendEditInvoice, METEditReasonCode))).allowEdit(!isNoDelivery);
    this.formRun().control(this.formRun().controlId(formControlStr(VendEditInvoice, METeditPriceReasonCode))).allowEdit(!isNoDelivery);
    this.object(fieldNum(VendInvoiceInfoLine, MetClaimLine)).allowEdit(!isNoDelivery);
}

/// <summary>
/// Vendor invoice form init
/// </summary>
public void init()
{
    next init();
    FormDataSource vendInvoiceInfoLine_ds = this;
    if (vendInvoiceInfoLine_ds)
    {
        vendInvoiceInfoLine_ds.object(fieldNum(VendInvoiceInfoLine, METUnitPriceInclGST)).allowEdit(false);
    }

}
